input.sparql:
SELECT ?work ?workLabel ?lcsh WHERE {
  ?work wdt:P921 wd:Q17167 .
  ?work wdt:P921 ?military_subject .
  ?military_subject wdt:P279* wd:Q178561 .
  OPTIONAL { ?work wdt:P244 ?lcsh }
  SERVICE wikibase:label { bd:serviceParam wikibase:language 'en' }
}

SELECT ?work ?workLabel ?subject ?subjectLabel ?lcsh WHERE {
  ?work wdt:P921 ?subject .
  ?subject wdt:P279* wd:Q8473 .
  ?work wdt:P921 wd:Q17167 .
  OPTIONAL { ?work wdt:P244 ?lcsh }
  SERVICE wikibase:label { bd:serviceParam wikibase:language 'en' }
}

SELECT DISTINCT ?war ?warLabel ?lcsh WHERE {
  ?war wdt:P361 wd:Q17167 .
  ?war wdt:P31/wdt:P279* wd:Q198 .
  OPTIONAL { ?war wdt:P244 ?lcsh }
  SERVICE wikibase:label { bd:serviceParam wikibase:language 'en' }
}

SELECT DISTINCT ?battle ?battleLabel ?war ?warLabel ?lcsh WHERE {
  ?battle wdt:P31 wd:Q178561 .
  ?battle wdt:P361* ?war .
  ?war wdt:P276*/wdt:P17 wd:Q220 .
  ?battle wdt:P585 ?date .
  FILTER(YEAR(?date) < 27 && YEAR(?date) > -509)
  OPTIONAL { ?battle wdt:P244 ?lcsh }
  SERVICE wikibase:label { bd:serviceParam wikibase:language 'en' }
}

SELECT ?legion ?legionLabel ?battle ?battleLabel WHERE {
  ?legion wdt:P31 wd:Q176799 .
  ?legion wdt:P17 wd:Q220 .
  ?legion rdfs:label ?legionName .
  FILTER(CONTAINS(?legionName, "Legion") || CONTAINS(?legionName, "Legio"))
  OPTIONAL { 
    ?battle wdt:P710 ?legion .
    ?battle wdt:P31 wd:Q178561 
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language 'en' }
}

SELECT ?concept ?conceptLabel ?lcsh WHERE {
  VALUES ?concept { 
    wd:Q1114493 wd:Q185443 wd:Q319985 wd:Q1128324 wd:Q5503963 
    wd:Q124988 wd:Q596373 wd:Q75813 wd:Q677316 wd:Q202161
  }
  OPTIONAL { ?concept wdt:P244 ?lcsh }
  SERVICE wikibase:label { bd:serviceParam wikibase:language 'en' }
}
